// Generated by scripts/sync-aiiolar-sheet.mjs from aiiolar. Do not edit by hand; run npm run sync:aiiolar-sheet.
import type { ReactNode } from 'react'
import { iconMarkup } from '@/lib/publish/contract'
import type { HbBlock, HbIcons, HbPage } from './types'
import { CodeBlock } from './CodeBlock'
import { Diagram } from './Diagram'
import { In } from './In'
import styles from './handbook.module.css'

const ink = (i?: string) => (i ? `ink-${i}` : undefined)
export const svg = (icons: HbIcons, name?: string): ReactNode => {
  const markup = iconMarkup(icons, name)
  return markup ? <span className="icon" aria-hidden dangerouslySetInnerHTML={{ __html: markup }} /> : null
}

export function Block({ block: b, icons, compact }: { block: HbBlock; icons: HbIcons; compact?: boolean }): ReactNode {
  switch (b.type) {
    case 'heading': return <In as="h3" className={[styles.h3, ink(b.ink)].filter(Boolean).join(' ')} text={b.text} icons={icons} />
    case 'paragraph': return <div className={styles.blk} data-frame={b.frame}><In as="p" className={ink(b.ink)} text={b.text} icons={icons} /></div>
    case 'bullets': return <div className={styles.blk} data-frame={b.frame}><ul className={styles.ul} data-style={b.style}>{b.items.map((x, i) => <In key={i} as="li" text={x} icons={icons} />)}</ul></div>
    case 'sidebox': return <aside className={[styles.side, ink(b.ink ?? 'purple')].join(' ')}><In as="b" text={b.title} icons={icons} /><ul>{b.items.map((x, i) => <In key={i} as="li" text={x} icons={icons} />)}</ul></aside>
    case 'table': return <div className={`${styles.blk} ${styles.scroll}`} data-frame={b.frame}><table className={styles.table}><thead><tr>{b.headers.map((x, i) => <In key={i} as="th" text={x} icons={icons} />)}</tr></thead><tbody>{b.rows.map((r, i) => <tr key={i} data-hl={b.highlightRow === i || undefined}>{r.map((c, j) => <In key={j} as="td" text={c} icons={icons} />)}</tr>)}</tbody></table></div>
    case 'code': return <CodeBlock lang={b.lang} lines={b.lines} note={b.note} result={b.result} />
    case 'callout': return <div className={styles.callout} data-callout={b.style}>{b.title && <In as="b" text={b.title} icons={icons} />}<In as="p" text={b.text} icons={icons} /></div>
    case 'concept': return <div className={styles.concept}><span className={styles.num}>{b.number}</span><In as="h3" text={b.title} icons={icons} />{b.tagline && <In as="p" text={b.tagline} icons={icons} />}</div>
    case 'labelrows': return <dl className={styles.labelrows}>{b.rows.map((r, i) => <div key={i}><dt>{svg(icons, r.icon)}<In text={r.label} icons={icons} /></dt><dd><In text={r.text} icons={icons} /></dd></div>)}</dl>
    case 'qa': return <details className={styles.qa}><In as="summary" text={b.q} icons={icons} /><ul className={styles.ul}>{b.a_bullets.map((x, i) => <In key={i} as="li" text={x} icons={icons} />)}</ul>{b.example_code && <CodeBlock lang="" lines={b.example_code} />}</details>
    case 'diagram': return <Diagram block={b} icons={icons} compact={compact} />
    default: return null
  }
}

export function HbPageView({ page, icons, id }: { page: HbPage; icons: HbIcons; id: string }) {
  if (page.kind === 'cover' && page.cover) {
    const c = page.cover
    return (
      <section id={id} className={`${styles.page} ${styles.cover}`}>
        <In as="h2" text={c.title} icons={icons} />
        {c.subtitle && <In as="p" text={c.subtitle} icons={icons} />}
        {c.icons.length > 0 && <div className={styles.coverIcons}>{c.icons.map((x, i) => <div key={i}>{svg(icons, x.icon)}<In as="b" text={x.label} icons={icons} />{x.sub && <In as="span" text={x.sub} icons={icons} />}</div>)}</div>}
        {c.pills.length > 0 && <div className={styles.pills}>{c.pills.map((p, i) => <In key={i} text={p} icons={icons} />)}</div>}
      </section>
    )
  }
  return (
    <section id={id} className={styles.page}>
      <header className={styles.pageHead}>
        <In as="h2" text={page.title} icons={icons} />
        {svg(icons, page.hero)}
      </header>
      {page.subtitle && <In as="p" className={styles.sub} text={page.subtitle} icons={icons} />}
      {page.blocks.map((b, i) => <Block key={i} block={b} icons={icons} />)}
      {page.aside && <In as="p" className={styles.aside} text={page.aside} icons={icons} />}
    </section>
  )
}
